shellCommands.command:
node --input-type=module -e "
import { mkdtemp, readFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createServer } from 'node:http';
import { createStore } from './lib/store.js';
import { createApp } from './server.js';

const dir = await mkdtemp(path.join(os.tmpdir(), 'books-app-'));
const filePath = path.join(dir, 'books.json');
const store = createStore(filePath);
const server = createServer(createApp(store));
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const { port } = server.address();
const base = 'http://127.0.0.1:' + port;

async function request(method, urlPath, body) {
  const res = await fetch(base + urlPath, {
    method,
    redirect: 'manual',
    headers: body ? { 'content-type': 'application/x-www-form-urlencoded' } : undefined,
    body,
  });
  return { status: res.status, location: res.headers.get('location'), text: await res.text() };
}

const home = await request('GET', '/');
if (home.status !== 200 || !home.text.includes('Currently reading') || !home.text.includes('Finished')) {
  throw new Error('home failed: ' + home.status);
}

const created = await request('POST', '/books', new URLSearchParams({
  title: 'The Dispossessed',
  author: 'Ursula K. Le Guin',
  notes: 'Share this with Sam.',
}).toString());
if (created.status !== 303 || !created.location?.startsWith('/books/')) {
  throw new Error('create failed: ' + JSON.stringify(created));
}

const page = await request('GET', created.location);
if (page.status !== 200 || !page.text.includes('The Dispossessed') || !page.text.includes('Ursula K. Le Guin') || !page.text.includes('Share this with Sam.')) {
  throw new Error('detail failed');
}

const id = created.location.split('/').pop();
const finished = await request('POST', '/books/' + id + '/finish');
if (finished.status !== 303) throw new Error('finish failed');

const after = await request('GET', '/');
if (!after.text.includes('The Dispossessed')) throw new Error('list missing book');
const finishedSection = after.text.split('<h2>Finished</h2>')[1] || '';
if (!finishedSection.includes('The Dispossessed')) throw new Error('not in finished');

const missing = await request('GET', '/books/nope');
if (missing.status !== 404) throw new Error('expected 404');

const raw = JSON.parse(await readFile(filePath, 'utf8'));
if (raw.books[0].status !== 'finished') throw new Error('json not finished');

const restarted = createStore(filePath);
const again = await restarted.get(id);
if (again?.title !== 'The Dispossessed') throw new Error('reload failed');

server.close();
console.log('ok', created.location);
"
